//#region src/tools/list-all-components.ts
const LIST_TOOL_NAME = "list-all-components";
async function addListAllComponentsTool(server, enabled) {
	server.tool({
		name: LIST_TOOL_NAME,
		title: "List All Components",
		description: "List all available UI components from the component library",
		enabled
	}, async () => {
		try {
			const manifest = await getManifest(server.ctx.custom?.request, server.ctx.custom?.manifestProvider);
			const componentList = formatComponentManifestMapToList(manifest, server.ctx.custom?.format ?? "markdown");
			await server.ctx.custom?.onListAllComponents?.({
				context: server.ctx.custom,
				manifest
			});
			return { content: [{
				type: "text",
				text: componentList
			}] };
		} catch (error) {
			return errorToMCPContent(error);
		}
	});
}

//#endregion
//#region src/tools/get-component-documentation.ts
const GET_TOOL_NAME = "get-component-documentation";
const GetComponentDocumentationInput = v.object({ componentId: v.string() });
async function addGetComponentDocumentationTool(server, enabled) {
	server.tool({
		name: GET_TOOL_NAME,
		title: "Get Documentation for Component",
		description: "Get detailed documentation for a specific UI component",
		schema: GetComponentDocumentationInput,
		enabled
	}, async (input) => {
		try {
			const component = (await getManifest(server.ctx.custom?.request, server.ctx.custom?.manifestProvider)).components[input.componentId];
			if (!component) {
				await server.ctx.custom?.onGetComponentDocumentation?.({
					context: server.ctx.custom,
					input: { componentId: input.componentId }
				});
				return {
					content: [{
						type: "text",
						text: `Component not found: "${input.componentId}". Use the list-all-components tool to see available components.`
					}],
					isError: true
				};
			}
			await server.ctx.custom?.onGetComponentDocumentation?.({
				context: server.ctx.custom,
				input: { componentId: input.componentId },
				foundComponent: component
			});
			return { content: [{
				type: "text",
				text: formatComponentManifest(component, server.ctx.custom?.format ?? "markdown")
			}] };
		} catch (error) {
			return errorToMCPContent(error);
		}
	});
}

