//#region src/index.ts
const createStorybookMcpHandler = async (options = {}) => {
	const adapter = new ValibotJsonSchemaAdapter();
	const server = new McpServer({
		name,
		version,
		description
	}, {
		adapter,
		capabilities: { tools: { listChanged: true } }
	}).withContext();
	if (options.onSessionInitialize) server.on("initialize", options.onSessionInitialize);
	await addListAllComponentsTool(server);
	await addGetComponentDocumentationTool(server);
	const transport = new HttpTransport(server, { path: null });
	return (async (req, context) => {
		return await transport.respond(req, {
			request: req,
			format: context?.format ?? options.format ?? "markdown",
			manifestProvider: context?.manifestProvider ?? options.manifestProvider,
			onListAllComponents: context?.onListAllComponents ?? options.onListAllComponents,
			onGetComponentDocumentation: context?.onGetComponentDocumentation ?? options.onGetComponentDocumentation
		});
	});
};

//#endregion
export { GET_TOOL_NAME, LIST_TOOL_NAME, MANIFEST_PATH, addGetComponentDocumentationTool, addListAllComponentsTool, createStorybookMcpHandler };